//! Cross-check `rsxcs` against reference values computed with libxc 7.1.2.
//!
//! The data file is generated by `tools/gen_reference.py`; see that script for
//! the column layout.

use rsxcs::{Order, Spin, Xc};

const DATA: &str = include_str!("data/libxc_7_1_2_reference.txt");

/// Relative and absolute tolerance.  The two implementations evaluate the
/// same expressions with different algebraic rearrangements, so agreement is
/// at the level of accumulated round-off rather than bit-for-bit.
const RTOL: f64 = 5e-10;
const ATOL: f64 = 1e-12;

#[derive(Debug)]
struct Case {
    name: String,
    id: u32,
    nspin: usize,
    npoints: usize,
    family: String,
    points: Vec<Vec<f64>>,
}

fn parse() -> Vec<Case> {
    let mut cases: Vec<Case> = Vec::new();
    for line in DATA.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with("# See") || line.starts_with("# Reference") {
            continue;
        }
        if let Some(rest) = line.strip_prefix("# ") {
            let mut it = rest.split_whitespace();
            let name = it.next().unwrap().to_string();
            let id: u32 = it.next().unwrap().parse().unwrap();
            let nspin: usize = it.next().unwrap().parse().unwrap();
            let npoints: usize = it.next().unwrap().parse().unwrap();
            let family = it.next().unwrap().to_string();
            cases.push(Case {
                name,
                id,
                nspin,
                npoints,
                family,
                points: Vec::new(),
            });
            continue;
        }
        let values: Vec<f64> = line
            .split_whitespace()
            .map(|v| v.parse().unwrap())
            .collect();
        cases.last_mut().unwrap().points.push(values);
    }
    cases
}

fn close(name: &str, what: &str, ip: usize, got: f64, want: f64) {
    let diff = (got - want).abs();
    let scale = want.abs().max(got.abs()).max(1.0);
    assert!(
        diff <= ATOL + RTOL * scale,
        "{name}: point {ip}: {what}: got {got:.17e}, libxc {want:.17e} (abs diff {diff:.3e})"
    );
}

fn check_slice(name: &str, what: &str, ip: usize, got: &[f64], want: &[f64]) {
    assert_eq!(got.len(), want.len(), "{name}: wrong length for {what}");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        close(name, &format!("{what}[{i}]"), ip, *g, *w);
    }
}

#[test]
fn reference_values_match_libxc_7_1_2() {
    let cases = parse();
    assert_eq!(cases.len(), 22 * 2, "unexpected number of reference cases");

    for case in &cases {
        let xc = Xc::from_name(&case.name)
            .unwrap_or_else(|_| panic!("functional {} is not implemented", case.name));
        assert_eq!(xc.functional().id(), case.id, "{}: id", case.name);
        assert_eq!(
            xc.functional().family().semilocal(),
            match case.family.as_str() {
                "lda" => rsxcs::Family::Lda,
                "gga" => rsxcs::Family::Gga,
                "mgga" => rsxcs::Family::Mgga,
                other => panic!("unknown family {other}"),
            },
            "{}: family",
            case.name
        );
        assert_eq!(case.points.len(), case.npoints);

        let pol = case.nspin == 2;
        let spin = if pol {
            Spin::Polarized
        } else {
            Spin::Unpolarized
        };
        assert_eq!(spin.n_spin(), case.nspin, "{}: spin", case.name);

        for (ip, vals) in case.points.iter().enumerate() {
            assert_eq!(vals.len(), 9 + 36);
            let (na, nb, saa, sab, sbb, ta, tb) = (
                vals[0], vals[1], vals[2], vals[3], vals[4], vals[5], vals[6],
            );

            let rho: Vec<f64> = if pol { vec![na, nb] } else { vec![na] };
            let sigma: Option<Vec<f64>> = match case.family.as_str() {
                "lda" => None,
                "gga" => Some(if pol { vec![saa, sab, sbb] } else { vec![saa] }),
                "mgga" => Some(if pol { vec![saa, sab, sbb] } else { vec![saa] }),
                _ => unreachable!(),
            };
            let tau: Option<Vec<f64>> = if case.family == "mgga" {
                Some(if pol { vec![ta, tb] } else { vec![ta] })
            } else {
                None
            };

            let out = xc
                .eval(
                    spin,
                    &rho,
                    sigma.as_deref(),
                    None,
                    tau.as_deref(),
                    Order::Fxc,
                )
                .unwrap();
            let fxc = out.fxc.as_ref().unwrap();

            let mut k = 9usize;
            let zk = vals[k];
            k += 1;
            close(&case.name, "exc", ip, out.exc[0], zk);

            let nspin = case.nspin;
            check_slice(&case.name, "vxc", ip, &out.vxc, &vals[k..k + 2][..nspin]);
            k += 2;

            let vsigma = &vals[k..k + 3];
            k += 3;
            let vtau = &vals[k..k + 2];
            k += 2;
            let v2rho2 = &vals[k..k + 3];
            k += 3;
            let v2rhosigma = &vals[k..k + 6];
            k += 6;
            let v2sigma2 = &vals[k..k + 6];
            k += 6;
            let v2rhotau = &vals[k..k + 4];
            k += 4;
            let v2sigmatau = &vals[k..k + 6];
            k += 6;
            let v2tau2 = &vals[k..k + 3];

            if case.family != "lda" {
                let nsig = if pol { 3 } else { 1 };
                check_slice(&case.name, "vsigma", ip, &out.vsigma, &vsigma[..nsig]);
            }
            if case.family == "mgga" {
                check_slice(&case.name, "vtau", ip, &out.vtau, &vtau[..nspin]);
            }

            // Compare the derivative arrays.  libxc stores 1 element for
            // unpolarized functionals and 3/6 for polarized ones; the
            // reference file is padded with zeros, so only compare the
            // meaningful prefix.
            let n2 = if pol { 3 } else { 1 };
            let nrs = if pol { 6 } else { 1 };
            let nlt = if pol { 4 } else { 1 };
            check_slice(&case.name, "v2rho2", ip, &fxc.v2rho2, &v2rho2[..n2]);

            if case.family != "lda" {
                check_slice(
                    &case.name,
                    "v2rhosigma",
                    ip,
                    &fxc.v2rhosigma,
                    &v2rhosigma[..nrs],
                );
                check_slice(&case.name, "v2sigma2", ip, &fxc.v2sigma2, &v2sigma2[..nrs]);
            }

            if case.family == "mgga" {
                check_slice(&case.name, "v2rhotau", ip, &fxc.v2rhotau, &v2rhotau[..nlt]);
                check_slice(
                    &case.name,
                    "v2sigmatau",
                    ip,
                    &fxc.v2sigmatau,
                    &v2sigmatau[..nrs],
                );
                check_slice(&case.name, "v2tau2", ip, &fxc.v2tau2, &v2tau2[..n2]);
            }
        }
    }
}

#[test]
fn registry_round_trips() {
    for &f in rsxcs::Functional::ALL {
        assert_eq!(rsxcs::Functional::from_id(f.id()), Some(f));
        assert_eq!(rsxcs::Functional::from_name(f.name()), Some(f));
    }
}
